'use strict';
(() => {
  const config=window.DOMI_SUPABASE,M=window.SchemaModel,$=id=>document.getElementById(id),stage=$('share-stage'),world=$('share-world');let map=null,view={x:0,y:0,z:1},drag=null;
  const showError=text=>{$('share-state').innerHTML=`<div><h2>Enlace no disponible</h2><p></p></div>`;$('share-state').querySelector('p').textContent=text;$('share-state').hidden=false;world.hidden=true;document.querySelector('.share-controls').hidden=true;};
  const colorFor=node=>map.modules.find(m=>m.id===node.module)?.color||'#267454';
  const height=node=>78+(node.fields?.length||0)*27;
  function point(item,side){const isGroup=map.groups.some(g=>g.id===item.id),w=isGroup?item.w:238,h=isGroup?item.h:height(item);return side==='left'?{x:item.x,y:item.y+h/2}:side==='right'?{x:item.x+w,y:item.y+h/2}:side==='top'?{x:item.x+w/2,y:item.y}:{x:item.x+w/2,y:item.y+h};}
  function bounds(){const items=[...map.groups,...map.entities,...map.cards];if(!items.length)return{x:0,y:0,w:600,h:400};const left=Math.min(...items.map(x=>x.x)),top=Math.min(...items.map(x=>x.y)),right=Math.max(...items.map(x=>x.x+(x.w||238))),bottom=Math.max(...items.map(x=>x.y+(x.h||height(x))));return{x:left,y:top,w:Math.max(300,right-left),h:Math.max(200,bottom-top)};}
  function apply(){world.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.z})`;$('share-zoom').textContent=Math.round(view.z*100)+'%';}
  function fit(){const b=bounds(),pad=70;view.z=Math.max(.2,Math.min(1.35,Math.min((stage.clientWidth-pad*2)/b.w,(stage.clientHeight-pad*2)/b.h)));view.x=(stage.clientWidth-b.w*view.z)/2-b.x*view.z;view.y=(stage.clientHeight-b.h*view.z)/2-b.y*view.z;apply();}
  function render(){
    $('share-title').textContent=map.title;$('share-groups').innerHTML='';$('share-nodes').innerHTML='';$('share-edge-layer').innerHTML='';
    for(const group of map.groups){const div=document.createElement('section');div.className='share-group';div.style.cssText=`left:${group.x}px;top:${group.y}px;width:${group.w}px;height:${group.h}px;--color:${group.color}`;const heading=document.createElement('h2');heading.textContent=group.name;div.append(heading);$('share-groups').append(div);}
    for(const node of map.entities){const div=document.createElement('article');div.className='share-node';div.style.cssText=`left:${node.x}px;top:${node.y}px;--color:${colorFor(node)}`;const header=document.createElement('header'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=node.name;small.textContent=node.label||map.modules.find(m=>m.id===node.module)?.name||'';header.append(strong,small);div.append(header);if(node.fields.length){const fields=document.createElement('div');fields.className='share-fields';for(const field of node.fields){const row=document.createElement('div');row.className='share-field';const name=document.createElement('span'),type=document.createElement('b');name.textContent=(field.pk?'PK · ':field.fk?'FK · ':'')+field.name;type.textContent=field.type;row.append(name,type);fields.append(row);}div.append(fields);}$('share-nodes').append(div);}
    const byId=new Map([...map.groups,...map.entities].map(x=>[x.id,x]));for(const edge of map.relationships){const a=byId.get(edge.from),b=byId.get(edge.to);if(!a||!b)continue;const p1=point(a,edge.fromPort),p2=point(b,edge.toPort),bend=Math.max(55,Math.abs(p2.x-p1.x)*.45),path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('class','share-edge');path.setAttribute('marker-end','url(#share-arrow)');path.setAttribute('d',`M ${p1.x} ${p1.y} C ${p1.x+bend} ${p1.y}, ${p2.x-bend} ${p2.y}, ${p2.x} ${p2.y}`);$('share-edge-layer').append(path);if(edge.label){const label=document.createElementNS('http://www.w3.org/2000/svg','text');label.setAttribute('class','share-edge-label');label.setAttribute('x',String((p1.x+p2.x)/2));label.setAttribute('y',String((p1.y+p2.y)/2-7));label.setAttribute('text-anchor','middle');label.textContent=edge.label;$('share-edge-layer').append(label);}}
    world.hidden=false;window.DomiCards.render($('share-cards'),map.cards);$('share-state').hidden=true;requestAnimationFrame(fit);
  }
  async function load(){const token=location.hash.slice(1);if(!/^[A-Za-z0-9_-]{43}$/.test(token))return showError('La URL está incompleta. Solicita un enlace nuevo al propietario del esquema.');try{const response=await fetch(config.url+'/functions/v1/schema-share',{method:'POST',headers:{'Content-Type':'application/json','apikey':config.publishableKey},body:JSON.stringify({action:'get',token}),signal:AbortSignal.timeout(30000)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'No se pudo abrir este esquema.');map=M.validate(data.snapshot);history.replaceState(null,'',location.pathname+location.search);$('share-meta').textContent=data.expiresAt?'Solo lectura · vence '+new Date(data.expiresAt).toLocaleDateString('es-DO'):'Vista de solo lectura';render();}catch(error){showError(error.message);}}
  function zoom(factor,x=stage.clientWidth/2,y=stage.clientHeight/2){const next=Math.max(.2,Math.min(2.5,view.z*factor)),wx=(x-view.x)/view.z,wy=(y-view.y)/view.z;view.x=x-wx*next;view.y=y-wy*next;view.z=next;apply();}
  $('share-zoom-in').onclick=()=>zoom(1.2);$('share-zoom-out').onclick=()=>zoom(1/1.2);$('share-fit').onclick=fit;stage.addEventListener('wheel',event=>{event.preventDefault();const box=stage.getBoundingClientRect();zoom(event.deltaY<0?1.12:1/1.12,event.clientX-box.left,event.clientY-box.top);},{passive:false});stage.addEventListener('pointerdown',event=>{if(event.button!==0)return;drag={id:event.pointerId,x:event.clientX,y:event.clientY,vx:view.x,vy:view.y};stage.setPointerCapture(event.pointerId);stage.classList.add('dragging');});stage.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.id)return;view.x=drag.vx+event.clientX-drag.x;view.y=drag.vy+event.clientY-drag.y;apply();});stage.addEventListener('pointerup',event=>{if(drag?.id===event.pointerId){drag=null;stage.classList.remove('dragging');}});window.addEventListener('resize',()=>map&&fit());load();
})();
